/** Browser copy of the last reduction percent. Cleared on logout so the next account does not inherit it. */
export const REDUCTION_PCT_STORAGE_KEY = 'sustainow_emissions_reduction_target_pct_v1';

export function clearReductionTargetSession(): void {
  if (typeof window === 'undefined') {
    return;
  }
  try {
    localStorage.removeItem(REDUCTION_PCT_STORAGE_KEY);
  } catch {
    // Storage can be blocked. The server profile remains the source of the saved percent.
  }
}
