export const INVENTORY_REFRESH_EVENT_TYPES = [
  'document.processed',
  'document.failed',
  'transactions.carbon_analysis.completed',
  'transactions.carbon_analysis.failed',
] as const;

export function isInventoryRefreshEvent(type: string | undefined): boolean {
  return INVENTORY_REFRESH_EVENT_TYPES.includes(
    String(type || '') as (typeof INVENTORY_REFRESH_EVENT_TYPES)[number]
  );
}

export type RefreshSide = {
  dataUpdatedAt: number;
  isFetching: boolean;
  isError: boolean;
};

export type InventoryRefreshHold = {
  statsUpdatedAt: number;
  dashboardUpdatedAt: number;
  sawStatsFetch: boolean;
  sawDashboardFetch: boolean;
  statsData: unknown;
  dashboardData: unknown;
  stale: boolean;
  retried?: boolean;
};

export function nextHoldObservation(
  hold: InventoryRefreshHold,
  stats: RefreshSide,
  dashboard: RefreshSide
): Pick<InventoryRefreshHold, 'sawStatsFetch' | 'sawDashboardFetch'> {
  return {
    sawStatsFetch: hold.sawStatsFetch
      || stats.isFetching
      || stats.isError
      || stats.dataUpdatedAt > hold.statsUpdatedAt,
    sawDashboardFetch: hold.sawDashboardFetch
      || dashboard.isFetching
      || dashboard.isError
      || dashboard.dataUpdatedAt > hold.dashboardUpdatedAt,
  };
}

export type RefreshDecision = 'hold' | 'release' | 'stale';

/**
 * Keep the previous Home hero and ISO line until both queries settle.
 * A failure on either side keeps that previous pair.
 */
export function decideCoordinatedRefresh(
  hold: Pick<InventoryRefreshHold, 'statsUpdatedAt' | 'dashboardUpdatedAt' | 'sawStatsFetch' | 'sawDashboardFetch'>,
  stats: RefreshSide,
  dashboard: RefreshSide
): RefreshDecision {
  const statsAdvanced = stats.dataUpdatedAt > hold.statsUpdatedAt;
  const dashboardAdvanced = dashboard.dataUpdatedAt > hold.dashboardUpdatedAt;
  const statsSettled = !stats.isFetching && (statsAdvanced || (hold.sawStatsFetch && stats.isError));
  const dashboardSettled = !dashboard.isFetching
    && (dashboardAdvanced || (hold.sawDashboardFetch && dashboard.isError));
  if (!statsSettled || !dashboardSettled) return 'hold';
  if (stats.isError || dashboard.isError) return 'stale';
  return 'release';
}

/**
 * The hold keeps both query timestamps. A saw-flag-only object makes
 * dataUpdatedAt > undefined false, so a successful pair never releases.
 */
function payloadRecord(response: unknown): Record<string, unknown> | null {
  if (!response || typeof response !== 'object') return null;
  const root = response as Record<string, unknown>;
  const nested = root.data;
  if (nested && typeof nested === 'object') return nested as Record<string, unknown>;
  return root;
}

export function readStatsInventoryKg(response: unknown): number {
  const carbon = payloadRecord(response)?.carbon;
  const total = Number((carbon as { totalCO2Emissions?: unknown } | undefined)?.totalCO2Emissions);
  return Number.isFinite(total) ? total : 0;
}

export function readDashboardInventoryKg(response: unknown): number {
  const verification = payloadRecord(response)?.transactionVerification as { scopes?: { totalKg?: unknown } } | undefined;
  const total = Number(verification?.scopes?.totalKg);
  return Number.isFinite(total) ? total : 0;
}

/** One extra paired read when the two payloads are still a full kilogram apart. */
export function inventoryPayloadsDisagree(statsKg: number, dashboardKg: number): boolean {
  if (!(statsKg > 0) || !(dashboardKg > 0)) return false;
  return Math.abs(statsKg - dashboardKg) > 1;
}

export function coordinateInventoryHold(
  hold: InventoryRefreshHold,
  stats: RefreshSide,
  dashboard: RefreshSide
): { decision: RefreshDecision; hold: InventoryRefreshHold } {
  const observed = nextHoldObservation(hold, stats, dashboard);
  const nextHold: InventoryRefreshHold = { ...hold, ...observed };
  return {
    decision: decideCoordinatedRefresh(nextHold, stats, dashboard),
    hold: nextHold,
  };
}
